changeSet.sql:
    CREATE
    OR REPLACE FUNCTION keycloak.insert_user_in_postgres()
RETURNS TRIGGER AS $$
    BEGIN
    RAISE
    NOTICE 'email: %, first_name: %, last_name: %, username: %',
        NEW.email, NEW.first_name, NEW.last_name, NEW.username;

    INSERT INTO postgres."user"
    VALUES (default, NEW.email, NEW.first_name, NEW.last_name, NEW.username, null);

    RETURN NEW;
    END
$$
    LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION keycloak.update_user_on_user_entity_change() RETURNS TRIGGER AS $$ BEGIN RAISE NOTICE 'email: %, first_name: %, last_name: %, username: %', NEW.email, NEW.first_name, NEW.last_name, NEW.username;
UPDATE postgres."user" SET last_name = NEW.last_name, first_name = NEW.first_name, email = NEW.email, username = NEW.username WHERE username = OLD.username;
RETURN NEW; END $$ LANGUAGE plpgsql;
